const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const wuhan = ee.Geometry.Point([114.3055, 30.5928]); // Wuhan, China coordinates
    const start2019 = '2019-02-01';
    const end2019 = '2019-02-28'; // February 2019
    const start2020 = '2020-02-01';
    const end2020 = '2020-02-29'; // February 2020 (leap year)
    const scale = 3000; // Use a reasonable scale to avoid memory issues for point-based reduction

    // 2. Data Acquisition & Check
    const collection = ee.ImageCollection('NOAA/GEOS_CFS/V2/PM25_DATA');

    // Filter for 2019
    let col2019 = collection.filterBounds(wuhan)
                            .filterDate(start2019, end2019)
                            .select('PM25');

    // Filter for 2020
    let col2020 = collection.filterBounds(wuhan)
                            .filterDate(start2020, end2020)
                            .select('PM25');

    const size2019 = await col2019.size().getInfo();
    const size2020 = await col2020.size().getInfo();

    if (size2019 === 0 || size2020 === 0) {
      console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);
      console.log('C1');
      return;
    }

    // 3. Processing: Calculate mean PM2.5 for each period
    const mean2019Image = col2019.mean();
    const mean2020Image = col2020.mean();

    // Check for valid pixels before reducing
    const count2019 = await mean2019Image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: wuhan,
      scale: scale,
      maxPixels: 1e9
    }).get('PM25').getInfo();

    const count2020 = await mean2020Image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: wuhan,
      scale: scale,
      maxPixels: 1e9
    }).get('PM25').getInfo();

    if (count2019 === 0 || count2020 === 0) {
      console.log(`2019 Valid Pixels: ${count2019}, 2020 Valid Pixels: ${count2020}`);
      console.log('C2');
      return;
    }

    // 4. Calculation
    const pm25_2019_info = await mean2019Image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: wuhan,
      scale: scale,
      maxPixels: 1e9
    }).get('PM25').getInfo();

    const pm25_2020_info = await mean2020Image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: wuhan,
      scale: scale,
      maxPixels: 1e9
    }).get('PM25').getInfo();

    // 5. Validation & Final Answer
    if (pm25_2019_info === null || isNaN(pm25_2019_info) || pm25_2020_info === null || isNaN(pm25_2020_info)) {
      console.log(`2019 PM2.5: ${pm25_2019_info}, 2020 PM2.5: ${pm25_2020_info}`);
      console.log('C3');
      return;
    }

    const pm25_2019 = pm25_2019_info;
    const pm25_2020 = pm25_2020_info;

    console.log(`2019 Images: ${size2019}, Valid Pixels: ${count2019}`);
    console.log(`2020 Images: ${size2020}, Valid Pixels: ${count2020}`);
    console.log(`Feb 2019 PM2.5 (µg/m³): ${pm25_2019.toFixed(2)}`);
    console.log(`Feb 2020 PM2.5 (µg/m³): ${pm25_2020.toFixed(2)}`);

    if (pm25_2020 > pm25_2019) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (error) {
    console.log(error.message);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
